arguments.command:
cd /tmp/sv-a0e4eb179ad04340bde7c0beb8ad1627/symbols && \
# Extract all dynamic symbols with their addresses and sizes, sorted by address
readelf -sW libmonosgen-2.0.so | awk '$4 == "FUNC" && $7 != "UND" {print $2, $3, $8}' | sort > syms.txt
wc -l syms.txt
# Now look up each PC address
echo "=== Thread 7020 (main) ===" 
for pc in 0000000000222098 00000000002241ac 00000000001abc80 000000000016de04; do
  echo -n "  pc $pc -> "
  awk -v addr="0x$pc" 'BEGIN{best="??"; bestaddr=0} {
    a=strtonum("0x"$1); s=strtonum("0x"$2);
    if (strtonum(addr) >= a && strtonum(addr) < a+s) {print $3; found=1; exit}
    if (a <= strtonum(addr) && a > bestaddr) {best=$3; bestaddr=a}
  } END{if(!found) print best"+0x"sprintf("%x",strtonum(addr)-bestaddr)}' found=0 syms.txt
done

echo "=== Thread 7046 (SGen worker) ==="
for pc in 00000000002f4b20 00000000002f4c84; do
  echo -n "  pc $pc -> "
  awk -v addr="0x$pc" 'BEGIN{best="??"; bestaddr=0} {
    a=strtonum("0x"$1); s=strtonum("0x"$2);
    if (strtonum(addr) >= a && strtonum(addr) < a+s) {print $3; found=1; exit}
    if (a <= strtonum(addr) && a > bestaddr) {best=$3; bestaddr=a}
