arguments.command:
cd /tmp/sv-a0e4eb179ad04340bde7c0beb8ad1627/symbols && \
DBG="dbg_out/libmonosgen-2.0.so.dbg"
# For the SGen worker addresses, try with --inlines and different options
echo "=== SGen worker - trying with readelf symtab ==="
# Get all FUNC symbols near those addresses from the full debug file
readelf -sW "$DBG" | awk '$4 == "FUNC" {print $2, $3, $8}' | sort > full_syms.txt
wc -l full_syms.txt

echo ""
echo "pc 0x2f4b20:"
awk -v addr="0x2f4b20" '{
  a=strtonum("0x"$1); s=strtonum("0x"$2);
  if (strtonum(addr) >= a && strtonum(addr) < a+s) {print $3" (exact, size="$2")"; found=1; exit}
}' found=0 full_syms.txt
