  if (a <= strtonum(addr) && a > bestaddr) {best=$3; bestaddr=a; bestsize=s}
} END{printf "%s+0x%x (base=0x%x size=0x%x)\n", best, strtonum(addr)-bestaddr, bestaddr, bestsize}' full_syms.txt

